package org.jscratch.runtime

import java.math.BigDecimal

/**
 * Scratch value conversions. Scratch values are dynamically typed: a value is a
 * number, a string or a boolean, and every block converts its inputs on use.
 * The rules here follow scratch-vm's `Cast` so compiled projects behave like
 * the editor does.
 *
 * Generated bytecode calls these as plain static methods, so every entry point
 * is a `@JvmStatic` with a stable signature.
 */
object Cast {
    /** JavaScript `Number(value)` with NaN preserved. */
    @JvmStatic
    fun toNumberOrNaN(value: Any?): Double = when (value) {
        null -> 0.0
        is Double -> value
        is Number -> value.toDouble()
        is Boolean -> if (value) 1.0 else 0.0
        is String -> parseNumber(value)
        else -> parseNumber(value.toString())
    }

    /**
     * JavaScript `Number(string)`. The grammar is checked by hand instead of a regex, since number
     * parsing is on the hot path of every comparison and arithmetic block that meets a string:
     * `[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?`, `[+-]?Infinity`, and the `0x`, `0o` and `0b` integer
     * forms. Anything else, including the whitespace and underscore forms `Double.parseDouble`
     * would accept, is NaN.
     */
    @JvmStatic
    internal fun parseNumber(raw: String): Double {
        val s = raw.trim()
        val n = s.length
        if (n == 0) return 0.0
        var i = 0
        val first = s[0]
        val negative = first == '-'
        if (negative || first == '+') i = 1
        if (i == n) return Double.NaN
        when (s[i]) {
            'I' -> {
                return when {
                    s.regionMatches(i, "Infinity", 0, 8) && i + 8 == n ->
                        if (negative) Double.NEGATIVE_INFINITY else Double.POSITIVE_INFINITY
                    else -> Double.NaN
                }
            }
            '0' -> {
                // The prefixed integer forms take no sign, like JavaScript.
                if (i == 0 && n > 2) {
                    val radix = when (s[1]) {
                        'x', 'X' -> 16
                        'o', 'O' -> 8
                        'b', 'B' -> 2
                        else -> 0
                    }
                    if (radix != 0) return parsePrefixed(s, radix)
                }
            }
        }

        // Validate the decimal grammar in one pass, tracking an integer value for the common case.
        var digits = 0
        var intValue = 0L
        var intDigits = 0
        while (i < n && s[i] in '0'..'9') {
            intValue = intValue * 10 + (s[i] - '0')
            digits++
            intDigits++
            i++
        }
        if (i < n && s[i] == '.') {
            i++
            while (i < n && s[i] in '0'..'9') {
                digits++
                i++
            }
        }
        if (digits == 0) return Double.NaN
        var exponent = false
        if (i < n && (s[i] == 'e' || s[i] == 'E')) {
            exponent = true
            i++
            if (i < n && (s[i] == '+' || s[i] == '-')) i++
            if (i == n || s[i] !in '0'..'9') return Double.NaN
            while (i < n && s[i] in '0'..'9') i++
        }
        if (i != n) return Double.NaN
        // A plain integer of up to 15 digits is exact in a double, so skip Double.parseDouble.
        if (!exponent && digits == intDigits && intDigits <= 15) {
            return if (negative) -intValue.toDouble() else intValue.toDouble()
        }
        return s.toDouble()
    }

    private fun parsePrefixed(s: String, radix: Int): Double {
        var value = 0.0
        for (i in 2 until s.length) {
            val d = Character.digit(s[i], radix)
            if (d < 0) return Double.NaN
            value = value * radix + d
        }
        return value
    }

    /** Scratch `toNumber`: like JavaScript `Number()` but NaN becomes 0. */
    @JvmStatic
    fun toNumber(value: Any?): Double {
        val n = toNumberOrNaN(value)
        return if (n.isNaN()) 0.0 else n
    }

    @JvmStatic
    fun toNumber(value: String): Double {
        val n = parseNumber(value)
        return if (n.isNaN()) 0.0 else n
    }

    @JvmStatic
    fun toBoolean(value: Any?): Boolean = when (value) {
        null -> false
        is Boolean -> value
        is String -> toBoolean(value)
        is Double -> value != 0.0 && !value.isNaN()
        is Number -> value.toDouble() != 0.0
        else -> true
    }

    @JvmStatic
    fun toBoolean(value: String): Boolean = !(
        value.isEmpty() || value == "0" ||
            value.equals("false", ignoreCase = true)
        )

    @JvmStatic
    fun toBoolean(value: Double): Boolean = value != 0.0 && !value.isNaN()

    @JvmStatic
    fun toString(value: Any?): String = when (value) {
        null -> ""
        is String -> value
        is Double -> toString(value)
        is Boolean -> toString(value)
        is Number -> toString(value.toDouble())
        else -> value.toString()
    }

    @JvmStatic
    fun toString(value: Boolean): String = if (value) "true" else "false"

    /** Formats a double the way JavaScript's `Number.prototype.toString` does. */
    @JvmStatic
    fun toString(value: Double): String {
        if (value.isNaN()) return "NaN"
        if (value.isInfinite()) return if (value > 0) "Infinity" else "-Infinity"
        if (value == 0.0) return "0"
        val abs = Math.abs(value)
        if (value == Math.rint(value) && abs < 1e21) {
            return if (abs < 9.007199254740992E15) value.toLong().toString() else BigDecimal(value).toPlainString()
        }

        val java = java.lang.Double.toString(value)
        if (abs >= 1e-6 && abs < 1e21) {
            return BigDecimal(java).toPlainString()
        }
        // Scientific notation: Java prints 1.0E-7, JavaScript prints 1e-7 and 1.5e+21.
        val e = java.indexOf('E')
        var mantissa = java.substring(0, e)
        if (mantissa.endsWith(".0")) mantissa = mantissa.dropLast(2)
        val exponent = java.substring(e + 1)
        return if (exponent.startsWith("-")) "${mantissa}e$exponent" else "${mantissa}e+$exponent"
    }

    /** Whether a value should be treated as an integer by `pick random` and list indexing. */
    @JvmStatic
    fun isInt(value: Any?): Boolean = when (value) {
        is Double -> value.isNaN() || value == Math.floor(value)
        is Number -> true
        is Boolean -> true
        is String -> !value.contains('.')
        else -> false
    }

    @JvmStatic
    fun isWhiteSpace(value: Any?): Boolean = value is String && value.trim().isEmpty()

    /**
     * Scratch comparison: numeric when both sides look like numbers, otherwise a
     * case-insensitive string comparison. Returns a negative number, zero or a
     * positive number.
     */
    @JvmStatic
    fun compare(a: Any?, b: Any?): Double {
        var n1 = toNumberOrNaN(a)
        var n2 = toNumberOrNaN(b)
        if (n1 == 0.0 && isWhiteSpace(a)) {
            n1 = Double.NaN
        } else if (n2 == 0.0 && isWhiteSpace(b)) {
            n2 = Double.NaN
        }
        if (n1.isNaN() || n2.isNaN()) {
            val s1 = toString(a).lowercase()
            val s2 = toString(b).lowercase()
            return when {
                s1 < s2 -> -1.0
                s1 > s2 -> 1.0
                else -> 0.0
            }
        }
        if (n1.isInfinite() && n2.isInfinite() && (n1 > 0) == (n2 > 0)) return 0.0
        return n1 - n2
    }

    @JvmStatic
    fun equals(a: Any?, b: Any?): Boolean = compare(a, b) == 0.0

    @JvmStatic
    fun lessThan(a: Any?, b: Any?): Boolean = compare(a, b) < 0

    @JvmStatic
    fun greaterThan(a: Any?, b: Any?): Boolean = compare(a, b) > 0

    const val LIST_INVALID = 0
    const val LIST_ALL = -1

    /**
     * Converts a Scratch list index ("last", "random", "any", "all" or a number)
     * into a 1-based index, [LIST_INVALID] or [LIST_ALL].
     */
    @JvmStatic
    fun toListIndex(index: Any?, length: Int, acceptAll: Boolean): Int {
        if (index !is Number) {
            when (index) {
                "all" -> return if (acceptAll) LIST_ALL else LIST_INVALID
                "last" -> return if (length > 0) length else LIST_INVALID
                "random", "any" -> return if (length > 0) 1 + (Math.random() * length).toInt() else LIST_INVALID
            }
        }

        val n = Math.floor(toNumber(index))
        if (n < 1 || n > length) return LIST_INVALID
        return n.toInt()
    }

    /** Parses a Scratch color argument (`#rrggbb` string or a packed number) into ARGB. */
    @JvmStatic
    fun toArgb(value: Any?): Int {
        if (value is String && value.startsWith("#")) {
            val hex = value.substring(1)
            val expanded =
                if (hex.length == 3) {
                    hex.map { "$it$it" }.joinToString("")
                } else {
                    hex
                }

            val rgb = expanded.toLongOrNull(16)?.toInt() ?: 0
            return (0xFF shl 24) or (rgb and 0xFFFFFF)
        }

        val n = toNumber(value).toLong()
        val alpha = ((n shr 24) and 0xFF).toInt()
        val rgb = (n and 0xFFFFFF).toInt()
        return ((if (alpha == 0) 0xFF else alpha) shl 24) or rgb
    }
}
